// Applied rules: [III③]
// Skipped rules: [III④: per user instruction to apply III③ alone this time and not reproduce the previous rewrite; C3: per user instruction to apply III③ alone this time and not reproduce the previous rewrite; II_vec: per user instruction to apply III③ alone this time and not reproduce the previous rewrite]
#[inline]
pub unsafe fn choices_fread(
    mut c: *mut choices_t,
    mut file: *mut FILE,
    mut input_delimiter: c_char,
) {
    let mut buffer_start: size_t = (*c).buffer_size;
    let mut capacity: size_t = INITIAL_BUFFER_CAPACITY as size_t;
    while capacity <= (*c).buffer_size {
        capacity = capacity.wrapping_mul(2 as size_t);
    }
    (*c).buffer =
        safe_realloc((*c).buffer as *mut c_void, capacity) as *mut c_char;
    loop {
        let bytes_read = fread(
            (*c).buffer.offset((*c).buffer_size as isize) as *mut c_void,
            1 as size_t,
            capacity.wrapping_sub((*c).buffer_size),
            file,
        );
        (*c).buffer_size = ((*c).buffer_size as c_ulong).wrapping_add(bytes_read) as size_t
            as size_t;
        if !((*c).buffer_size == capacity) {
            break;
        }
        capacity = capacity.wrapping_mul(2 as size_t);
        (*c).buffer = safe_realloc((*c).buffer as *mut c_void, capacity)
            as *mut c_char;
    }
    (*c).buffer = safe_realloc(
        (*c).buffer as *mut c_void,
        (*c).buffer_size.wrapping_add(1 as size_t),
    ) as *mut c_char;
    let fresh0 = (*c).buffer_size;
    (*c).buffer_size = (*c).buffer_size.wrapping_add(1);
    *(*c).buffer.offset(fresh0 as isize) = '\0' as i32 as c_char;
    let mut line_end: *const c_char = (*c).buffer.offset((*c).buffer_size as isize);
    let mut line: *mut c_char = (*c).buffer.offset(buffer_start as isize);
    loop {
        let mut nl: *mut c_char = memchr(
            line as *const c_void,
            input_delimiter as c_int,
            line_end.offset_from(line as *const c_char) as size_t,
        ) as *mut c_char;
        if !nl.is_null() {
            let fresh1 = nl;
            nl = nl.offset(1);
            *fresh1 = '\0' as i32 as c_char;
        }
        if *line != 0 {
            choices_add(c, line);
        }
        line = nl;
        if !(!line.is_null() && line < line_end as *mut c_char) {
            break;
        }
    }
}

